DROP TABLE IF EXISTS customer_churn;

CREATE TABLE customer_churn (
    CustomerID VARCHAR(20),
    Gender VARCHAR(10),
    Age INT,
    Tenure INT,
    Contract VARCHAR(20),
    InternetService VARCHAR(20),
    TechSupport VARCHAR(5),
    PaymentMethod VARCHAR(30),
    MonthlyCharges FLOAT,
    TotalCharges FLOAT,
    Complaints INT,
    Churn INT
);

